window.products.push({"id":1106420,"name":"MIU France Perforated Spoon","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/41gicXNfuES._AC_SL1200_.jpg","description":"MIU France polished stainless steel perforated cooking spoon, item # 10906. 14-inch long handle with a 3-inch perforated head. Seamless construction. Made of heavy stainless steel. Decorative 3-dot handle. Great for serving peas, corn or fruit salads. The perforated head drains excess liquid back into the serving bowl. Can be stored on a hanging tool bar or pot rack. Dishwasher safe, remove immediately and wipe dry to minimize water spots.","images":["https://m.media-amazon.com/images/I/41gicXNfuES._AC_SL1200_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"MIU France","source_asin":"B000VWBUII","category_path":"Home & Kitchen"},"sku":"BM-1106420","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B000VWBUII","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B000VWBUII","price_pending":true,"merchant_ready":false});
